import React, { useState } from "react";

const ROLES = ["Buyer", "Seller", "Realtor"];

const matchListing = (listing, buyerRequests) =>
  buyerRequests.some(
    (request) =>
      request.location.toLowerCase() === listing.location.toLowerCase() &&
      listing.price <= request.budget
  );

export default function App() {
  const [activeRole, setActiveRole] = useState("Buyer");
  const [listings, setListings] = useState([]);
  const [buyerRequests, setBuyerRequests] = useState([]);

  const [sellerTitle, setSellerTitle] = useState("");
  const [sellerLocation, setSellerLocation] = useState("");
  const [sellerPrice, setSellerPrice] = useState("");

  const [buyerLocation, setBuyerLocation] = useState("");
  const [buyerBudget, setBuyerBudget] = useState("");

  const handleAddListing = (event) => {
    event.preventDefault();
    if (!sellerTitle.trim() || !sellerLocation.trim() || !sellerPrice) return;

    setListings((prev) => [
      ...prev,
      {
        id: Date.now(),
        title: sellerTitle.trim(),
        location: sellerLocation.trim(),
        price: Number(sellerPrice),
      },
    ]);

    setSellerTitle("");
    setSellerLocation("");
    setSellerPrice("");
  };

  const handleAddBuyerRequest = (event) => {
    event.preventDefault();
    if (!buyerLocation.trim() || !buyerBudget) return;

    setBuyerRequests((prev) => [
      ...prev,
      {
        id: Date.now(),
        location: buyerLocation.trim(),
        budget: Number(buyerBudget),
      },
    ]);

    setBuyerLocation("");
    setBuyerBudget("");
  };

  return (
    <div className="app-shell">
      <style>{`
        :root {
          color-scheme: dark;
          --bg: #0c1428;
          --panel: #151f3e;
          --panel-strong: #1d2c56;
          --text: #eef2ff;
          --muted: #9ab1d1;
          --border: #2e3b5d;
          --accent: #61dafb;
          --accent-strong: #47bfff;
          --success: #69e18d;
          --danger: #ff6d75;
        }

        * {
          box-sizing: border-box;
        }

        html,
        body,
        #root {
          margin: 0;
          min-height: 100%;
          font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
            sans-serif;
          background: radial-gradient(circle at top, #182548 0%, #090d1b 65%);
          color: var(--text);
        }

        .app-shell {
          max-width: 1100px;
          margin: 0 auto;
          padding: 32px 24px 48px;
        }

        .app-header {
          display: flex;
          flex-wrap: wrap;
          align-items: flex-start;
          justify-content: space-between;
          gap: 22px;
          margin-bottom: 32px;
        }

        .eyebrow {
          margin: 0 0 12px;
          color: var(--accent);
          text-transform: uppercase;
          letter-spacing: 0.22em;
          font-size: 0.82rem;
        }

        .app-header h1 {
          margin: 0;
          font-size: clamp(2rem, 3vw, 3rem);
          line-height: 1.05;
          max-width: 720px;
        }

        .role-switcher {
          display: flex;
          gap: 10px;
          flex-wrap: wrap;
        }

        .role-button {
          border: 1px solid var(--border);
          background: transparent;
          color: var(--text);
          padding: 10px 18px;
          border-radius: 999px;
          cursor: pointer;
          transition: border-color 0.2s ease, background 0.2s ease, transform 0.2s ease;
        }

        .role-button:hover,
        .role-button.active {
          background: var(--accent);
          border-color: var(--accent);
          color: #08101e;
          transform: translateY(-1px);
        }

        .card {
          background: rgba(18, 28, 54, 0.95);
          border: 1px solid var(--border);
          border-radius: 24px;
          padding: 28px;
          box-shadow: 0 24px 70px rgba(0, 0, 0, 0.22);
          margin-bottom: 24px;
        }

        .card-header h2 {
          margin: 0;
          font-size: 1.5rem;
        }

        .card-body {
          margin-top: 22px;
        }

        .form-grid {
          display: grid;
          gap: 18px;
          margin-bottom: 24px;
        }

        label {
          display: grid;
          gap: 10px;
          color: var(--muted);
          font-size: 0.95rem;
        }

        input {
          width: 100%;
          border-radius: 14px;
          border: 1px solid var(--border);
          padding: 14px 16px;
          background: #101a33;
          color: var(--text);
          outline: none;
          transition: border-color 0.2s ease;
        }

        input:focus {
          border-color: var(--accent);
        }

        .primary-button,
        .ghost-button {
          border-radius: 14px;
          padding: 14px 20px;
          cursor: pointer;
          transition: transform 0.18s ease, background 0.2s ease;
          font: inherit;
        }

        .primary-button {
          border: none;
          background: var(--accent);
          color: #08101e;
          width: fit-content;
        }

        .ghost-button {
          border: 1px solid var(--accent);
          background: transparent;
          color: var(--accent);
        }

        .primary-button:hover,
        .ghost-button:hover {
          transform: translateY(-1px);
        }

        .summary-title {
          margin: 0 0 12px;
          color: var(--text);
        }

        .summary-list {
          margin: 0;
          padding-left: 18px;
          color: var(--muted);
        }

        .summary-list li {
          margin-bottom: 10px;
        }

        .empty-state {
          margin: 0;
          color: var(--muted);
        }

        .table-wrapper {
          overflow-x: auto;
        }

        table {
          width: 100%;
          border-collapse: collapse;
          color: var(--text);
        }

        th,
        td {
          padding: 16px 14px;
          text-align: left;
          border-bottom: 1px solid var(--border);
        }

        thead th {
          color: var(--muted);
          text-transform: uppercase;
          letter-spacing: 0.08em;
          font-size: 0.82rem;
        }

        tbody tr:hover {
          background: rgba(255, 255, 255, 0.03);
        }

        .badge {
          display: inline-flex;
          align-items: center;
          padding: 6px 12px;
          border-radius: 999px;
          font-size: 0.82rem;
          font-weight: 600;
        }

        .match {
          background: rgba(94, 226, 145, 0.16);
          color: var(--success);
        }

        .no-match {
          background: rgba(255, 109, 109, 0.16);
          color: var(--danger);
        }

        .empty-table {
          padding: 42px 0;
          text-align: center;
          color: var(--muted);
        }

        .dashboard-copy {
          margin-bottom: 20px;
          color: var(--muted);
        }

        .dashboard-footer {
          margin-top: 20px;
          color: var(--muted);
        }
      `}</style>

      <header className="app-header">
        <div>
          <p className="eyebrow">Real Agent</p>
          <h1>Real Estate experience for buyers, sellers, and realtors</h1>
        </div>
        <div className="role-switcher">
          {ROLES.map((role) => (
            <button
              key={role}
              className={`role-button ${activeRole === role ? "active" : ""}`}
              onClick={() => setActiveRole(role)}
            >
              {role}
            </button>
          ))}
        </div>
      </header>

      {activeRole === "Seller" && (
        <section className="card">
          <div className="card-header">
            <h2>Seller View</h2>
          </div>
          <div className="card-body">
            <form className="form-grid" onSubmit={handleAddListing}>
              <label>
                Property title
                <input
                  value={sellerTitle}
                  onChange={(event) => setSellerTitle(event.target.value)}
                  placeholder="Modern loft"
                />
              </label>

              <label>
                Location
                <input
                  value={sellerLocation}
                  onChange={(event) => setSellerLocation(event.target.value)}
                  placeholder="City / neighborhood"
                />
              </label>

              <label>
                Price
                <input
                  type="number"
                  value={sellerPrice}
                  onChange={(event) => setSellerPrice(event.target.value)}
                  placeholder="Asking price"
                />
              </label>

              <button type="submit" className="primary-button">
                Save property
              </button>
            </form>

            <div>
              <h3 className="summary-title">Saved listings</h3>
              {listings.length === 0 ? (
                <p className="empty-state">No properties added yet.</p>
              ) : (
                <ul className="summary-list">
                  {listings.map((item) => (
                    <li key={item.id}>
                      {item.title} · {item.location} · $
                      {item.price.toLocaleString()}
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        </section>
      )}

      {activeRole === "Buyer" && (
        <section className="card">
          <div className="card-header">
            <h2>Buyer View</h2>
          </div>
          <div className="card-body">
            <form className="form-grid" onSubmit={handleAddBuyerRequest}>
              <label>
                Desired location
                <input
                  value={buyerLocation}
                  onChange={(event) => setBuyerLocation(event.target.value)}
                  placeholder="City / neighborhood"
                />
              </label>

              <label>
                Budget
                <input
                  type="number"
                  value={buyerBudget}
                  onChange={(event) => setBuyerBudget(event.target.value)}
                  placeholder="Maximum budget"
                />
              </label>

              <button type="submit" className="primary-button">
                Save request
              </button>
            </form>

            <div>
              <h3 className="summary-title">Saved buyer requests</h3>
              {buyerRequests.length === 0 ? (
                <p className="empty-state">No buyer requests yet.</p>
              ) : (
                <ul className="summary-list">
                  {buyerRequests.map((item) => (
                    <li key={item.id}>
                      {item.location} · up to ${item.budget.toLocaleString()}
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        </section>
      )}

      {activeRole === "Realtor" && (
        <section className="card">
          <div className="card-header">
            <h2>Realtor Dashboard</h2>
          </div>
          <div className="card-body">
            <p className="dashboard-copy">
              Review properties and identify listings that match buyer budgets
              in the same location.
            </p>

            <div className="table-wrapper">
              <table>
                <thead>
                  <tr>
                    <th>Title</th>
                    <th>Location</th>
                    <th>Price</th>
                    <th>Status</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {listings.length === 0 ? (
                    <tr>
                      <td colSpan="5" className="empty-table">
                        No listings available.
                      </td>
                    </tr>
                  ) : (
                    listings.map((item) => {
                      const matched = matchListing(item, buyerRequests);
                      return (
                        <tr key={item.id}>
                          <td>{item.title}</td>
                          <td>{item.location}</td>
                          <td>${item.price.toLocaleString()}</td>
                          <td>
                            <span className={`badge ${matched ? "match" : "no-match"}`}>
                              {matched ? "Match" : "No Match"}
                            </span>
                          </td>
                          <td>
                            <button
                              type="button"
                              className="ghost-button"
                              onClick={() => alert("Subscription Required")}
                            >
                              View Contact
                            </button>
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>

            <div className="dashboard-footer">
              {listings.length} listings · {buyerRequests.length} requests
            </div>
          </div>
        </section>
      )}
    </div>
  );
}
